using Microsoft.Extensions.AI;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Quality;
using Microsoft.Extensions.AI.Evaluation.Reporting;
using Aspire.Hosting.Testing;
using Microsoft.Extensions.DependencyInjection;

namespace MyApp.Evaluation;

[TestClass]
public sealed class EvaluationTests
{
    private static DistributedApplicationTestingBuilder? s_appHost;
    private static IChatClient? s_chatClient;

    [ClassInitialize]
    public static async Task Setup(TestContext context)
    {
        s_appHost = await DistributedApplicationTestingBuilder.CreateAsync<Projects.MyApp_AppHost>();
        await s_appHost.BuildAsync();
        var app = await s_appHost.StartAsync();
        s_chatClient = app.Services.GetRequiredService<IChatClient>();
    }

    [ClassCleanup]
    public static async Task Cleanup()
    {
        if (s_appHost is IAsyncDisposable disposable)
        {
            await disposable.DisposeAsync();
        }
    }

    [TestMethod]
    public async Task Chat_ReturnsRelevantResponse()
    {
        // Arrange
        var evaluators = new IEvaluator[]
        {
            new RelevancyEvaluator(),
            new CoherenceEvaluator(),
            new FluencyEvaluator(),
        };

        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "What is the capital of France?")
        };

        // Act
        var response = await s_chatClient!.GetResponseAsync(messages);
        var modelResponse = response.Text ?? string.Empty;

        // Evaluate
        var result = await EvaluateAsync(evaluators, messages, modelResponse);

        // Assert
        foreach (var evaluation in result)
        {
            Assert.IsFalse(
                evaluation.Value.Rating == EvaluationRating.Inconclusive,
                $"Evaluator '{evaluation.Key}' returned inconclusive.");
        }
    }

    [TestMethod]
    public async Task Chat_GroundedResponse()
    {
        // Arrange
        var evaluators = new IEvaluator[]
        {
            new GroundednessEvaluator(),
            new RelevancyEvaluator(),
        };

        var context = "Paris is the capital and largest city of France.";
        var messages = new List<ChatMessage>
        {
            new(ChatRole.System, $"Use the following context to answer: {context}"),
            new(ChatRole.User, "What is the capital of France?")
        };

        // Act
        var response = await s_chatClient!.GetResponseAsync(messages);
        var modelResponse = response.Text ?? string.Empty;

        // Evaluate
        var result = await EvaluateAsync(evaluators, messages, modelResponse);

        foreach (var evaluation in result)
        {
            Assert.IsFalse(
                evaluation.Value.Rating == EvaluationRating.Inconclusive,
                $"Evaluator '{evaluation.Key}' returned inconclusive.");
        }
    }

    private static async Task<Dictionary<string, EvaluationResult>> EvaluateAsync(
        IEnumerable<IEvaluator> evaluators,
        IList<ChatMessage> messages,
        string modelResponse)
    {
        var results = new Dictionary<string, EvaluationResult>();

        foreach (var evaluator in evaluators)
        {
            var turnContext = new TurnContext(messages, new ChatMessage(ChatRole.Assistant, modelResponse));
            var evaluationResult = await evaluator.EvaluateAsync(turnContext);
            foreach (var kvp in evaluationResult)
            {
                results[kvp.Key] = kvp.Value;
            }
        }

        return results;
    }
}

